#pragma once

#define GFL_MAP_1(pred, a) pred(a)
#define GFL_MAP_2(pred, a, b) pred(a), pred(b)
#define GFL_MAP_3(pred, a, b, c) pred(a), pred(b), pred(c)
#define GFL_MAP_4(pred, a, b, c, d) pred(a), pred(b), pred(c), pred(d)
#define GFL_MAP_5(pred, a, b, c, d, e) pred(a), pred(b), pred(c), pred(d), pred(e)
#define GFL_MAP_6(pred, a, b, c, d, e, f) pred(a), pred(b), pred(c), pred(d), pred(e), pred(f)
#define GFL_MAP_7(pred, a, b, c, d, e, f, g) pred(a), pred(b), pred(c), pred(d), pred(e), pred(f), pred(g)
#define GFL_MAP_8(pred, a, b, c, d, e, f, g, h) pred(a), pred(b), pred(c), pred(d), pred(e), pred(f), pred(g), pred(h)

#define GFL_GET_MAP(_1, _2, _3, _4, _5, _6, _7, _8, _9, NAME, ...) NAME
#define GFL_MAP(pred, ...) GFL_GET_MAP(__VA_ARGS__, GFL_MAP_ONLY_SUPPORTS_UP_TO_8_ARGUMENTS, GFL_MAP_8, GFL_MAP_7, GFL_MAP_6, GFL_MAP_5, GFL_MAP_4, GFL_MAP_3, GFL_MAP_2, GFL_MAP_1)(pred, __VA_ARGS__)
#define GFL_COUNT(...) GFL_GET_MAP(__VA_ARGS__, 9, 8, 7, 6, 5, 4, 3, 2, 1)

#define GFL_STRINGIFY(x) #x
#define GFL_MAP_STRINGIFY(...) GFL_MAP(GFL_STRINGIFY, __VA_ARGS__)

#define GFL_DISABLE_COPY(typeName)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             \
    typeName(typeName const&) = delete;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        \
    typeName& operator=(typeName const&) = delete

#define GFL_DISABLE_MOVE(typeName)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             \
    typeName(typeName&&) = delete;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             \
    typeName& operator=(typeName&&) = delete

#define GFL_DISABLE_COPY_AND_MOVE(typeName)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    \
    GFL_DISABLE_COPY(typeName);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                \
    GFL_DISABLE_MOVE(typeName)
